import type React from 'react'
import { MotiView } from 'moti'
import { AlignJustify, LayoutGrid } from 'lucide-react-native'
import { APPEAR_DURATION } from '@/constants'
import { AnimatedTouchableOpacity } from '@/components'
import Animated, {
	Extrapolation,
	interpolate,
	interpolateColor,
	type SharedValue,
	useAnimatedStyle
} from 'react-native-reanimated'
import { ProjectGroupLayout } from '@/types'
import { colors, type Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

type LayoutToggleButtonProps = {
	isLoading: boolean
	layout: ProjectGroupLayout
	onToggleLayout: () => void
	backgroundAnimation: SharedValue<number>
	scrollY: SharedValue<number>
}

export const LayoutToggleButton: React.FC<LayoutToggleButtonProps> = ({
	isLoading,
	layout,
	onToggleLayout,
	backgroundAnimation,
	scrollY
}) => {
	const { theme } = useTheme()

	const backgroundFadeStyle = useAnimatedStyle(() => {
		const backgroundColor = colors[theme].gray[75]
		return {
			backgroundColor: interpolateColor(
				backgroundAnimation.get(),
				[0, 1],
				[`${backgroundColor}ff`, `${backgroundColor}00`]
			)
		}
	})
	const fadingStyle = useAnimatedStyle(() => {
		const opacity = interpolate(
			scrollY.get(),
			[0, 100],
			[1, 0],
			Extrapolation.CLAMP
		)
		const translateY = interpolate(
			scrollY.get(),
			[0, 100],
			[0, -100],
			Extrapolation.CLAMP
		)
		return {
			opacity,
			transform: [{ translateY }]
		}
	})

	return (
		<Animated.View style={fadingStyle}>
			<AnimatedTouchableOpacity
				disabled={isLoading}
				onPress={onToggleLayout}
				style={[styles.layoutContainer(theme), backgroundFadeStyle]}
			>
				<MotiView
					from={{ opacity: 0 }}
					animate={{ opacity: isLoading ? 0 : 1 }}
					transition={{
						type: 'timing',
						duration: APPEAR_DURATION
					}}
					style={styles.layoutPosition}
				>
					<MotiView
						from={{ opacity: 1 }}
						animate={{ opacity: layout === ProjectGroupLayout.LIST ? 0 : 1 }}
						exit={{ opacity: layout === ProjectGroupLayout.LIST ? 1 : 0 }}
						transition={{
							type: 'timing',
							duration: 300
						}}
						style={styles.iconPosition}
					>
						<AlignJustify size={24} color={colors[theme].gray[900]} />
					</MotiView>
					<MotiView
						from={{ opacity: 1 }}
						animate={{ opacity: layout === ProjectGroupLayout.LIST ? 1 : 0 }}
						exit={{ opacity: layout === ProjectGroupLayout.LIST ? 0 : 1 }}
						transition={{
							type: 'timing',
							duration: 300
						}}
						style={styles.iconPosition}
					>
						<LayoutGrid size={24} color={colors[theme].gray[900]} />
					</MotiView>
				</MotiView>
			</AnimatedTouchableOpacity>
		</Animated.View>
	)
}

const styles = defineStyles({
	layoutContainer: (theme: Theme) => ({
		zIndex: 1,
		backgroundColor: colors[theme].gray[75],
		borderRadius: 4
	}),
	layoutPosition: {
		position: 'relative',
		width: 24,
		height: 24
	},
	iconPosition: {
		position: 'absolute',
		top: 0,
		left: 0
	}
})
